});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/workflows/instances/%7Bid%7D/history?filters%5Bactivity_types%5D%5B%5D=SOME_ARRAY_VALUE"),
};
